"use client";

import {
  Card,
  CardContent,
  CardFooter,
  CardHeader,
} from "@/components/ui/card";
import {
  Form,
  FormField,
  FormItem,
  FormLabel,
  FormControl,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import * as z from "zod";
import { useForm } from "react-hook-form";
import React from "react";
import { zodResolver } from "@hookform/resolvers/zod";
import { PrimaryButton } from "@/app/components/ButtonPrimary";

const schema = z
  .object({
    nomeCompleto: z.string().min(1, {
      message: "Nome completo é obrigatório",
    }),
    email: z.string(),
    cpf: z
      .string()
      .trim()
      .min(14, { message: "CPF deve ser formatado por XXX.XXX.XXX-XX" })
      .regex(/^\d{3}.\d{3}.\d{3}-\d{2}$/),
    senha: z
      .string()
      .min(6, { message: "Senha deve ter pelo menos 6 caracteres" }),
    confirmarSenha: z.string(),
  })
  .refine((data) => data.senha === data.confirmarSenha, {
    message: "As senhas não coincidem",
    path: ["confirmarSenha"],
  });

type FormData = z.infer<typeof schema>;

function Page() {
  const form = useForm<FormData>({ resolver: zodResolver(schema) });

  return (
    <Card
      className="min-w-[326px] w-[30vw] min-h-[326px] h-[75vh]
                  bg-white rounded-[20px] overflow-auto"
      style={{ boxShadow: "4px 4px 10px rgba(0, 0, 0, 0.25)" }}
    >
      <CardHeader className="pt-12">
        <div className="w-full flex justify-center mt-8 sm:mt-12">
          <span className="font-baloo2 font-semibold text-[2.25rem] leading-[58px] text-center text-blue-900">
            Cadastrar
          </span>
        </div>
      </CardHeader>
      <CardContent className="w-full flex justify-center items-start">
        <Form {...form}>
          <form className="flex flex-col gap-1.5 w-full sm:w-[360px] max-w-full p-4 relative">
            <FormField
              control={form.control}
              name="nomeCompleto"
              render={({ field }) => (
                <FormItem className="w-full">
                  <FormLabel className="text-sm font-medium text-foreground">
                    Nome Completo
                  </FormLabel>
                  <FormControl>
                    <Input
                      {...field}
                      placeholder="Ex. Julia Firmino"
                      className="w-full bg-white border border-border rounded-md h-12 px-1"
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="email"
              render={({ field }) => (
                <FormItem className="w-full mt-1">
                  <FormLabel className="text-sm font-medium text-foreground">
                    Email
                  </FormLabel>
                  <FormControl>
                    <Input
                      {...field}
                      type="email"
                      placeholder="julia@example.com"
                      className="w-full bg-white border border-border rounded-md h-12 px-1 text-sm text-foreground/50"
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="cpf"
              render={({ field }) => (
                <FormItem className="w-full">
                  <FormLabel className="text-sm font-medium text-foreground">
                    CPF
                  </FormLabel>
                  <FormControl>
                    <Input
                      {...field}
                      placeholder="Ex. Julia Firmino"
                      className="w-full bg-white border border-border rounded-md h-12 px-1"
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="senha"
              render={({ field }) => (
                <FormItem className="w-full">
                  <FormLabel className="text-sm font-medium text-foreground">
                    Senha
                  </FormLabel>
                  <FormControl>
                    <Input
                      {...field}
                      placeholder="Ex. Julia Firmino"
                      className="w-full bg-white border border-border rounded-md h-12 px-1"
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="confirmarSenha"
              render={({ field }) => (
                <FormItem className="w-full">
                  <FormLabel className="text-sm font-medium text-foreground">
                    Confirmar senha
                  </FormLabel>
                  <FormControl>
                    <Input
                      {...field}
                      placeholder=""
                      className="w-full bg-white border border-border rounded-md h-12 px-1"
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
          </form>
        </Form>
      </CardContent>
      <CardFooter className="w-full flex justify-center mgt-0">
        <PrimaryButton>Cadastrar</PrimaryButton>
      </CardFooter>
    </Card>
  );
}

export default Page;
